def fill_footer_details(apps, schema_editor):
    """Put AJ's real details into the existing settings row (only where still blank/old default)
    and create the 4 policy pages with empty text."""
    SiteSettings = apps.get_model("myapp", "SiteSettings")
    PolicyPage = apps.get_model("myapp", "PolicyPage")
    s, _ = SiteSettings.objects.get_or_create(pk=1)
    if not s.phone:
        s.phone = "+91 9751431501"
    if s.order_hours_en in OLD_HOURS:
        s.order_hours_en = "Every day · Lunch 12 PM – 6 PM"
        s.order_hours_ta = "தினமும் · மதிய உணவு 12 – 6 மணி"
    if s.address_en in OLD_ADDR:
        s.address_en = "1H/1668, Nigilesan Nagar,\n1st Street, Tuticorin,\nTamil Nadu"
        s.address_ta = "1H/1668, நிகிலேசன் நகர்,\n1வது தெரு, தூத்துக்குடி,\nதமிழ்நாடு"
    s.save()
    for slug, en, ta in POLICIES:
        PolicyPage.objects.get_or_create(slug=slug, defaults={"title_en": en, "title_ta": ta})


